_load('agent_v4.workers', '"""Official-mechanics worker hiring and deterministic task assignment."""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Literal\n\nfrom agent_v4.routing import manhattan_distance, nearest_shed_access, next_move, shed_access_positions\nfrom agent_v4.state import GameState, Position\n\nTaskKind = Literal["HARVEST", "WATER", "DIG", "PLANT", "DEPOSIT"]\n\n\n@dataclass(frozen=True)\nclass WorkTask:\n    kind: TaskKind\n    target: Position\n    priority: int\n    urgency: int = 0\n    economic_value: float = 0.0\n    crop: str | None = None\n    owner: int | None = None\n\n\n@dataclass(frozen=True)\nclass Unit:\n    index: int  # zero is farmer; positive values are hand indices + 1\n    position: Position\n    carried_count: int\n\n\ndef fibonacci(index: int) -> int:\n    if index < 0:\n        raise ValueError("hire index cannot be negative")\n    a, b = 1, 1\n    for _ in range(index):\n        a, b = b, a + b\n    return a\n\n\ndef hire_cost(hires_today: int, multiplier: int = 1) -> int:\n    return multiplier * fibonacci(hires_today)\n\n\ndef units(state: GameState) -> tuple[Unit, ...]:\n    return (Unit(0, state.farmer, state.carried_count),) + tuple(\n        Unit(hand.index + 1, hand.position, hand.carried_count) for hand in state.hands\n    )\n\n\ndef choose_task(unit: Unit, tasks: list[WorkTask], reserved: set[Position]) -> WorkTask | None:\n    available = [task for task in tasks if task.target not in reserved and (task.owner is None or task.owner == unit.index)]\n    if not available:\n        return None\n    return max(\n        available,\n        key=lambda task: (\n            task.priority * 100 + task.urgency * 10 + task.economic_value - manhattan_distance(unit.position, task.target),\n            unit.position == task.target,\n            -task.target[1],\n            -task.target[0],\n        ),\n    )\n\n\ndef task_action(state: GameState, unit: Unit, task: WorkTask | None) -> list[str]:\n    if task is None:\n        if unit.carried_count:\n            target = nearest_shed_access(unit.position, state.board_size)\n            return ["DROP"] if unit.position in shed_access_positions(state.board_size) else [next_move(unit.position, target, state.board_size)]\n        return ["PASS"]\n    if unit.position != task.target:\n        return [next_move(unit.position, task.target, state.board_size)]\n    if task.kind == "PLANT" and task.crop:\n        return ["PLANT", task.crop]\n    if task.kind == "DEPOSIT":\n        return ["DROP"]\n    return [task.kind]\n\n\ndef assign_tasks(state: GameState, tasks: list[WorkTask]) -> dict[int, WorkTask | None]:\n    assignments: dict[int, WorkTask | None] = {unit.index: None for unit in units(state)}\n    reserved: set[Position] = set()\n    seed_remaining = {crop: state.seed_count(crop) for crop in state.seeds}\n    available_units = list(units(state))\n    ordered = sorted(tasks, key=lambda task: (-task.priority, -task.urgency, -task.economic_value, task.target[1], task.target[0]))\n    for task in ordered:\n        if task.target in reserved or (task.kind == "PLANT" and (not task.crop or seed_remaining.get(task.crop, 0) <= 0)):\n            continue\n        eligible = [unit for unit in available_units if task.owner is None or task.owner == unit.index]\n        if not eligible:\n            continue\n        selected_unit = min(eligible, key=lambda unit: (manhattan_distance(unit.position, task.target), unit.index))\n        assignments[selected_unit.index] = task\n        available_units.remove(selected_unit)\n        reserved.add(task.target)\n        if task.kind == "PLANT" and task.crop:\n            seed_remaining[task.crop] -= 1\n    return assignments\n\n\ndef hiring_orders(state: GameState, max_hands: int, estimated_work: int, cash_reserve: float = 200.0) -> list[list[str]]:\n    if not 0 <= max_hands <= 4:\n        raise ValueError("max_hands must be between 0 and 4")\n    current = len(state.hands)\n    slots = max(0, max_hands - current)\n    if slots == 0 or state.remaining_turns <= 2 or state.hour >= 22:\n        return []\n    orders: list[list[str]] = []\n    money = state.money\n    # A hire made now can contribute only on later turns and vanishes overnight.\n    useful_turns = min(23 - state.hour, state.remaining_turns - 1)\n    for offset in range(slots):\n        cost = hire_cost(state.hires_today + offset)\n        marginal_work = max(0, estimated_work - (current + len(orders) + 1))\n        expected_value = min(useful_turns, marginal_work) * 2.0\n        if useful_turns <= 0 or marginal_work <= 0 or expected_value <= cost or money - cost < cash_reserve:\n            break\n        orders.append(["HIRE"])\n        money -= cost\n    return orders\n')
_load('agent_v4.strategy', '"""V4 task scheduling over frozen V3 crop and market decisions."""\n\nfrom __future__ import annotations\n\nfrom collections import Counter\n\nfrom agent_v3.strategy import SAFE_ACTION, COMPACT_ROUTE, CropPlan, Task, _capacity_safe_allocation\n\nfrom agent_v4 import crops\nfrom agent_v4.endgame import is_final_day\nfrom agent_v4.market import build_market_orders\nfrom agent_v4.state import GameState\nfrom agent_v4.workers import WorkTask, assign_tasks, hiring_orders, task_action, units\n\nSUPPORTED_HAND_LIMITS = (0, 1, 2, 3, 4)\nSUPPORTED_CAPACITIES = (12, 16, 20, 24)\nEXTENDED_ROUTE = COMPACT_ROUTE + tuple(\n    sorted(\n        ((x, y) for y in range(5) for x in range(5) if (x, y) not in COMPACT_ROUTE),\n        key=lambda position: (abs(4 - position[0]) + abs(4 - position[1]), -position[1], -position[0]),\n    )\n)\n\n\ndef validate_hand_limit(max_hands: int) -> int:\n    if max_hands not in SUPPORTED_HAND_LIMITS:\n        raise ValueError(f"max_hands must be one of {SUPPORTED_HAND_LIMITS}")\n    return max_hands\n\n\ndef select_managed_tiles(state: GameState, capacity: int) -> tuple[tuple[int, int], ...]:\n    if capacity not in SUPPORTED_CAPACITIES:\n        raise ValueError(f"capacity must be one of {SUPPORTED_CAPACITIES}")\n    return tuple(position for position in EXTENDED_ROUTE if not state.tile_at(position).is_locked)[:capacity]\n\n\ndef build_crop_plan(state: GameState, capacity: int) -> CropPlan:\n    from agent_v4.economics import score_all_crops\n    from agent_v4.market import live_crop_prices\n    positions = select_managed_tiles(state, capacity)\n    existing = [crop for position in positions if (crop := crops.crop_type(state.tile_at(position))) is not None]\n    scores = score_all_crops(state.step, live_crop_prices(state))\n    allocation = _capacity_safe_allocation(scores, existing, len(positions))\n    targets = {}\n    assigned = Counter(existing)\n    for position in positions:\n        current = crops.crop_type(state.tile_at(position))\n        if current is not None:\n            targets[position] = current\n    for position in positions:\n        tile = state.tile_at(position)\n        if position in targets or not (crops.is_usable_empty(tile) or crops.is_weed(tile)):\n            continue\n        deficits = [(wanted - assigned.get(crop, 0), scores[crop].score, crop) for crop, wanted in allocation.items()]\n        viable = [item for item in deficits if item[0] > 0]\n        if viable:\n            _, _, chosen = max(viable, key=lambda item: (item[0], item[1], item[2]))\n            targets[position] = chosen\n            assigned[chosen] += 1\n    return CropPlan(scores, allocation, targets)\n\n\ndef generate_tasks(state: GameState, capacity: int, plan: CropPlan) -> list[Task]:\n    tasks = []\n    for position in select_managed_tiles(state, capacity):\n        tile = state.tile_at(position)\n        if crops.is_crop(tile):\n            if crops.should_harvest(tile, state.day, is_final_day(state.day)):\n                tasks.append(Task("HARVEST", position, 100))\n            elif crops.is_exhausted_recurring(tile, state.day):\n                tasks.append(Task("DIG", position, 80))\n            elif not is_final_day(state.day) and crops.needs_water(tile):\n                tasks.append(Task("WATER", position, 90 + int(tile.raw.get("consecutive_unwatered", 0))))\n        elif crops.is_weed(tile) and position in plan.targets:\n            tasks.append(Task("DIG", position, 80))\n        elif crops.is_usable_empty(tile) and position in plan.targets:\n            crop = plan.targets[position]\n            if state.seed_count(crop) > 0:\n                tasks.append(Task("PLANT", position, 70, crop))\n    return tasks\n\n\ndef build_tasks(state: GameState, capacity: int, plan) -> list[WorkTask]:\n    result = []\n    prices = state.market_prices\n    for task in generate_tasks(state, capacity, plan):\n        tile = state.tile_at(task.target)\n        crop = crops.crop_type(tile) or task.crop\n        value = float(prices.get(crop, 0)) if crop else 0.0\n        urgency = 3 if task.kind == "HARVEST" else int(tile.raw.get("consecutive_unwatered", 0)) if task.kind == "WATER" and isinstance(tile.raw, dict) else 0\n        result.append(WorkTask(task.kind, task.target, task.priority, urgency, value, task.crop))\n    return result\n\n\ndef decide(state: GameState, max_hands: int, capacity: int = 12) -> dict[str, list]:\n    validate_hand_limit(max_hands)\n    plan = build_crop_plan(state, capacity)\n    empty_targets = {position: crop for position, crop in plan.targets.items() if crops.is_usable_empty(state.tile_at(position))}\n    market = build_market_orders(state, empty_targets)\n    tasks = build_tasks(state, capacity, plan)\n    estimated_work = len(tasks) + len(empty_targets)\n    hires = hiring_orders(state, max_hands, estimated_work)\n    assignments = assign_tasks(state, tasks)\n    active_units = units(state)\n    farmer = task_action(state, active_units[0], assignments.get(0))\n    hands = [task_action(state, unit, assignments.get(unit.index)) for unit in active_units[1:]]\n    # Preserve V3\'s no-new-planting endgame policy through its crop plan and stop speculative hires.\n    if is_final_day(state.day) and state.remaining_turns < 4:\n        hires = []\n    return {"farmer": farmer, "hands": hands, "market": market + hires}\n')
_load('agent_v6.state', '"""V6 observation parsing for workers, structures, and livestock."""\nfrom __future__ import annotations\nfrom dataclasses import dataclass\nfrom typing import Any, Mapping\nfrom agent_v4.state import GameState as V4GameState\nPosition = tuple[int, int]\n\n@dataclass(frozen=True)\nclass StructureState:\n    position: Position\n    kind: str\n    animal: str | None\n    consecutive_unfed: int = 0\n    fed_today: bool = False\n    cared_today: bool = False\n    yield_units: int = 0\n    fertilizer_available: bool = False\n    placed_day: int | None = None\n\n@dataclass(frozen=True)\nclass GameState(V4GameState):\n    structures: tuple[StructureState, ...]\n\n    @classmethod\n    def from_observation(cls, obs: Any) -> "GameState":\n        base = V4GameState.from_observation(obs)\n        found = []\n        for tile in base.iter_tiles():\n            raw = tile.raw\n            if not isinstance(raw, Mapping) or raw.get("kind") not in ("COOP", "PASTURE"):\n                continue\n            found.append(StructureState(tile.position, str(raw["kind"]), raw.get("animal"),\n                int(raw.get("consecutive_unfed", 0)), bool(raw.get("fed_today", False)),\n                bool(raw.get("cared_today", False)), int(raw.get("yield_units", 0)),\n                bool(raw.get("fertilizer_available", False)),\n                int(raw["placed_day"]) if raw.get("placed_day") is not None else None))\n        return cls(**base.__dict__, structures=tuple(found))\n\n    def unit_inventory(self, index: int) -> Mapping[str, int]:\n        if index == 0:\n            return self.carried\n        hand = index - 1\n        return self.hands[hand].carried if 0 <= hand < len(self.hands) else {}\n')
_load('agent_v6.animals', '"""Official-mechanics livestock model and deterministic animal work generation."""\nfrom __future__ import annotations\nfrom dataclasses import dataclass\nfrom typing import Literal, Mapping\nfrom agent_v4.routing import nearest_shed_access\nfrom agent_v4.strategy import EXTENDED_ROUTE\nfrom agent_v4.workers import WorkTask, Unit\nfrom agent_v6.state import GameState\n\nSpecies = Literal["GOOSE", "COW", "SHEEP"]\nMode = Literal["NONE", "GOOSE_ONLY", "COW_ONLY", "SHEEP_ONLY", "MIXED"]\nANIMAL_DATA = {\n    "GOOSE": {"cost": 300, "structure": "COOP", "first_yield_day": 4, "interval": 1, "max_held": 4, "product": "EGG"},\n    "COW": {"cost": 400, "structure": "PASTURE", "first_yield_day": 8, "interval": 2, "max_held": 6, "product": "MILK"},\n    "SHEEP": {"cost": 500, "structure": "PASTURE", "first_yield_day": 6, "interval": 3, "max_held": 6, "product": "WOOL"},\n}\nPRODUCT_BASE = {"EGG": 50, "MILK": 160, "WOOL": 200}\n\n@dataclass(frozen=True)\nclass AnimalEconomics:\n    species: Species\n    remaining_cycles: int\n    product_revenue: float\n    fertilizer_value: float\n    purchase_cost: float\n    structure_cost: float\n    feed_cost: float\n    labor_cost: float\n    crop_opportunity_cost: float\n    expected_value: float\n\ndef production_cycles(species: Species, current_day: int, placed_day: int | None = None) -> int:\n    data = ANIMAL_DATA[species]\n    start = current_day if placed_day is None else placed_day\n    first = start + int(data["first_yield_day"])\n    return 0 if first > 29 else 1 + (29 - first) // int(data["interval"])\n\ndef animal_roi(species: Species, current_day: int, prices: Mapping[str, int], *, structure_cost: float = 0.0,\n               crop_opportunity_cost: float = 500.0, labor_action_value: float = 2.0,\n               fertilizer_enabled: bool = False) -> AnimalEconomics:\n    data = ANIMAL_DATA[species]\n    cycles, days = production_cycles(species, current_day), max(0, 30 - current_day)\n    product_revenue = cycles * float(prices.get(str(data["product"]), PRODUCT_BASE[str(data["product"])]))\n    feed_cost = days * float(prices.get("WHEAT", 25))\n    labor_cost = (days + 3 + cycles) * labor_action_value\n    fertilizer_value = days * float(prices.get("FERTILIZER", 100)) if fertilizer_enabled else 0.0\n    purchase = float(data["cost"])\n    value = product_revenue + fertilizer_value - purchase - structure_cost - feed_cost - labor_cost - crop_opportunity_cost\n    return AnimalEconomics(species, cycles, product_revenue, fertilizer_value, purchase, structure_cost,\n                           feed_cost, labor_cost, crop_opportunity_cost, value)\n\ndef configured_species(mode: Mode, caps: Mapping[str, int]) -> tuple[Species, ...]:\n    if mode == "NONE": return ()\n    names = ("GOOSE", "COW", "SHEEP") if mode == "MIXED" else (mode.removesuffix("_ONLY"),)\n    return tuple(name for name in names for _ in range(max(0, int(caps.get(name, 0)))))  # type: ignore[misc]\n\ndef structure_positions(state: GameState, count: int) -> tuple[tuple[int, int], ...]:\n    usable = [p for p in EXTENDED_ROUTE if not state.tile_at(p).is_locked]\n    return tuple(reversed(usable[-count:])) if count else ()\n\ndef carried_total(state: GameState, item: str) -> int:\n    return sum(int(state.unit_inventory(i).get(item, 0)) for i in range(len(state.hands) + 1))\n\ndef required_market_orders(state: GameState, species: tuple[Species, ...], positions, buy_allowed=True):\n    orders = []\n    for product in ("EGG", "MILK", "WOOL"):\n        if (n := int(state.shed.get(product, 0))): orders.append(["SELL", product, n])\n    existing = {s.position: s for s in state.structures}\n    available = {name: int(state.shed.get(name, 0)) + carried_total(state, name) for name in ANIMAL_DATA}\n    for wanted, position in zip(species, positions):\n        if existing.get(position) and existing[position].animal: continue\n        if buy_allowed and available[wanted] <= 0:\n            orders.append(["BUY_ANIMAL", wanted, 1]); available[wanted] += 1\n    living = sum(1 for s in state.structures if s.animal)\n    wheat = int(state.shed.get("WHEAT", 0)) + carried_total(state, "WHEAT")\n    if living and wheat < living: orders.append(["BUY_PRODUCT", "WHEAT", living - wheat])\n    return orders\n\ndef animal_tasks(state: GameState, species: tuple[Species, ...], positions, fertilizer_enabled=False):\n    tasks = []; existing = {s.position: s for s in state.structures}; unit_count = len(state.hands) + 1\n    if fertilizer_enabled:\n        carrier = next((i for i in range(unit_count) if int(state.unit_inventory(i).get("FERTILIZER", 0)) > 0), None)\n        candidates = [t for t in state.iter_tiles() if isinstance(t.raw, dict) and t.raw.get("kind") == "PLANT"\n                      and int(t.raw.get("fertilized_until_day", -1)) < state.day]\n        if carrier is not None and candidates and state.day < 29:\n            target = max(candidates, key=lambda t: (float(state.market_prices.get(t.raw.get("crop"), 0)), -t.position[1], -t.position[0]))\n            tasks.append(WorkTask("FERTILIZE", target.position, 75, owner=carrier,\n                                  economic_value=float(state.market_prices.get(target.raw.get("crop"), 0))))  # type: ignore[arg-type]\n        elif carrier is None and int(state.shed.get("FERTILIZER", 0)) > 0 and state.day < 29:\n            tasks.append(WorkTask("PICKUP_FERTILIZER", nearest_shed_access(state.farmer, state.board_size), 74))  # type: ignore[arg-type]\n    for wanted, pos in zip(species, positions):\n        tile, structure = state.tile_at(pos).raw, existing.get(pos)\n        if structure is None:\n            kind = "DIG" if tile is not None else ("BUILD_COOP" if wanted == "GOOSE" else "BUILD_PASTURE")\n            tasks.append(WorkTask(kind, pos, 125, economic_value=1000.0)); continue  # type: ignore[arg-type]\n        if structure.animal is None:\n            carrier = next((i for i in range(unit_count) if int(state.unit_inventory(i).get(wanted, 0)) > 0), None)\n            if carrier is not None: tasks.append(WorkTask("PLACE_ANIMAL", pos, 124, owner=carrier, crop=wanted))  # type: ignore[arg-type]\n            elif int(state.shed.get(wanted, 0)) > 0:\n                tasks.append(WorkTask("PICKUP_ANIMAL", nearest_shed_access(state.farmer, state.board_size), 124, crop=wanted))  # type: ignore[arg-type]\n            continue\n        if not structure.fed_today:\n            feeder = next((i for i in range(unit_count) if int(state.unit_inventory(i).get("WHEAT", 0)) > 0), None)\n            if feeder is not None: tasks.append(WorkTask("FEED", pos, 150 + structure.consecutive_unfed * 20, owner=feeder))\n            elif int(state.shed.get("WHEAT", 0)) > 0:\n                tasks.append(WorkTask("PICKUP_FEED", nearest_shed_access(state.farmer, state.board_size), 149 + structure.consecutive_unfed * 20))  # type: ignore[arg-type]\n            continue\n        if structure.yield_units:\n            tasks.append(WorkTask("HARVEST", pos, 130, economic_value=float(structure.yield_units * PRODUCT_BASE[str(ANIMAL_DATA[structure.animal]["product"])])))\n        elif not structure.cared_today and production_cycles(structure.animal, state.day, structure.placed_day) > 0:  # type: ignore[arg-type]\n            tasks.append(WorkTask("CARE", pos, 65))  # type: ignore[arg-type]\n        elif fertilizer_enabled and structure.fertilizer_available:\n            tasks.append(WorkTask("COLLECT_FERTILIZER", pos, 55))  # type: ignore[arg-type]\n    return tasks\n\ndef format_animal_action(state: GameState, unit: Unit, task: WorkTask | None):\n    special = {"BUILD_COOP", "BUILD_PASTURE", "PLACE_ANIMAL", "PICKUP_ANIMAL", "PICKUP_FEED", "PICKUP_FERTILIZER", "FEED", "CARE", "COLLECT_FERTILIZER"}\n    if task is None or task.kind not in special: return None\n    if unit.position != task.target:\n        from agent_v4.routing import next_move\n        return [next_move(unit.position, task.target, state.board_size)]\n    if task.kind == "PLACE_ANIMAL": return ["PLACE", str(task.crop)]\n    if task.kind == "PICKUP_ANIMAL": return ["PICKUP", str(task.crop), "1"]\n    if task.kind == "PICKUP_FEED": return ["PICKUP", "WHEAT", "1"]\n    if task.kind == "PICKUP_FERTILIZER": return ["PICKUP", "FERTILIZER", "1"]\n    return [str(task.kind)]\n')
_load('agent_v6.strategy', '"""V6: frozen V4 crops plus isolated, capacity-aware livestock tasks."""\nfrom __future__ import annotations\nfrom collections import Counter\nfrom typing import Mapping\nfrom agent_v4 import crops\nfrom agent_v4.economics import score_all_crops\nfrom agent_v4.market import live_crop_prices\nfrom agent_v4.strategy import EXTENDED_ROUTE\nfrom agent_v3.strategy import CropPlan, _capacity_safe_allocation\nfrom agent_v4.endgame import is_final_day\nfrom agent_v4.market import build_market_orders\nfrom agent_v4.strategy import SAFE_ACTION\nfrom agent_v4.workers import WorkTask, assign_tasks, hiring_orders, task_action, units\nfrom agent_v6.animals import Mode, animal_roi, animal_tasks, configured_species, format_animal_action, required_market_orders, structure_positions\nfrom agent_v6.state import GameState\n\ndef _crop_tasks(state: GameState, capacity: int):\n    positions = tuple(p for p in EXTENDED_ROUTE if not state.tile_at(p).is_locked)[:capacity]\n    existing = [c for p in positions if (c := crops.crop_type(state.tile_at(p))) is not None]\n    scores = score_all_crops(state.step, live_crop_prices(state)); allocation = _capacity_safe_allocation(scores, existing, len(positions))\n    targets = {}; assigned = Counter(existing)\n    for p in positions:\n        if (c := crops.crop_type(state.tile_at(p))) is not None: targets[p] = c\n    for p in positions:\n        tile = state.tile_at(p)\n        if p in targets or not (crops.is_usable_empty(tile) or crops.is_weed(tile)): continue\n        viable = [(n-assigned.get(c,0), scores[c].score, c) for c,n in allocation.items() if n-assigned.get(c,0)>0]\n        if viable:\n            _,_,c=max(viable); targets[p]=c; assigned[c]+=1\n    plan = CropPlan(scores, allocation, targets); result=[]\n    for p in positions:\n        tile=state.tile_at(p); kind=None; priority=0; crop=crops.crop_type(tile); urgency=0\n        if crops.is_crop(tile):\n            if crops.should_harvest(tile,state.day,is_final_day(state.day)): kind,priority="HARVEST",100\n            elif crops.is_exhausted_recurring(tile,state.day): kind,priority="DIG",80\n            elif not is_final_day(state.day) and crops.needs_water(tile): kind,priority="WATER",90; urgency=int(tile.raw.get("consecutive_unwatered",0))\n        elif crops.is_weed(tile) and p in targets: kind,priority="DIG",80\n        elif crops.is_usable_empty(tile) and p in targets and state.seed_count(targets[p])>0: kind,priority,crop="PLANT",70,targets[p]\n        if kind: result.append(WorkTask(kind,p,priority,urgency,float(state.market_prices.get(crop,0)) if crop else 0.0,crop))\n    return plan, result\n\ndef decide(state: GameState, max_hands=4, capacity=24, *, mode: Mode="NONE", caps: Mapping[str, int] | None=None, fertilizer_enabled=False):\n    if mode == "NONE":\n        from agent_v4.strategy import decide as v4_decide\n        return v4_decide(state, max_hands, capacity)\n    caps = dict(caps or {"GOOSE": 1, "COW": 1, "SHEEP": 1})\n    proposed = configured_species(mode, caps)\n    affordable = tuple(s for s in proposed if animal_roi(s, state.day, state.market_prices, fertilizer_enabled=fertilizer_enabled).expected_value > 0)\n    species = proposed if any(s.animal for s in state.structures) else affordable\n    positions = structure_positions(state, len(species)); crop_capacity = max(12, capacity - len(positions))\n    plan, crop_tasks = _crop_tasks(state, crop_capacity)\n    empty = {p: c for p, c in plan.targets.items() if state.tile_at(p).is_empty}\n    market = build_market_orders(state, empty)\n    if any(s.animal for s in state.structures):\n        # Retain a survival reserve instead of selling wheat and buying it back.\n        reserve = sum(1 for s in state.structures if s.animal)\n        adjusted = []\n        for order in market:\n            if order[:2] == ["SELL", "WHEAT"]:\n                quantity = max(0, int(order[2]) - reserve)\n                if quantity: adjusted.append(["SELL", "WHEAT", quantity])\n            else: adjusted.append(order)\n        market = adjusted\n    market += required_market_orders(state, species, positions, state.day < 29)\n    tasks = crop_tasks + animal_tasks(state, species, positions, fertilizer_enabled)\n    hires = hiring_orders(state, max_hands, len(tasks) + len(empty))\n    assignments = assign_tasks(state, tasks); active = units(state); actions = []\n    for unit in active:\n        task = assignments.get(unit.index); actions.append(format_animal_action(state, unit, task) or task_action(state, unit, task))\n    if is_final_day(state.day) and state.remaining_turns < 4: hires = []\n    return {"farmer": actions[0], "hands": actions[1:], "market": market + hires}\n')
_load('agent_v8.state', '"""V8 parses only the official shared farm payload for opponent state."""\nfrom __future__ import annotations\nfrom dataclasses import dataclass\nfrom typing import Any,Mapping\nfrom agent_v6.state import GameState as V6GameState,Position,StructureState\n\ndef _get(v:Any,k:str,d=None):return v.get(k,d) if isinstance(v,Mapping) else getattr(v,k,d)\n\n@dataclass(frozen=True)\nclass OpponentFarm:\n    player:int;money:float;farmer:Position;hands:tuple[Position,...]\n    unlocked_quadrants:tuple[str,...];hires_today:int;tiles:tuple[tuple[Any,...],...]\n\n@dataclass(frozen=True)\nclass GameState(V6GameState):\n    opponent:OpponentFarm\n    @classmethod\n    def from_observation(cls,obs:Any)->"GameState":\n        base=V6GameState.from_observation(obs);farms=_get(obs,\'farms\',()) or ();oid=1-base.player\n        if oid<0 or oid>=len(farms):raise ValueError(\'opponent public farm unavailable\')\n        f=farms[oid];farmer=_get(f,\'farmer\',(0,0));hands=_get(f,\'hands\',()) or ()\n        opponent=OpponentFarm(oid,float(_get(f,\'money\',0)),(int(farmer[0]),int(farmer[1])),\n            tuple((int(p[0]),int(p[1])) for p in hands),tuple(_get(f,\'unlocked_quadrants\',()) or ()),\n            int(_get(f,\'hires_today\',0)),tuple(tuple(row) for row in (_get(f,\'tiles\',()) or ())))\n        return cls(**base.__dict__,opponent=opponent)\n')
_load('agent_v8.opponent', '"""Compact reset-safe model of legally observable opponent production."""\nfrom __future__ import annotations\nfrom collections import Counter,deque\nfrom dataclasses import dataclass,field\nfrom typing import Literal,Mapping\nfrom agent_v8.state import GameState,OpponentFarm\nMode=Literal[\'CONTROL\',\'STATIC_SNAPSHOT\',\'PIPELINE\',\'FULL_OPPONENT\']\nCROP_DATA={\'WHEAT\':(2,6),\'CARROT\':(2,4),\'TOMATO\':(8,4),\'STRAWBERRY\':(10,4),\'MELON\':(10,6)}\nANIMAL_PRODUCT={\'GOOSE\':\'EGG\',\'COW\':\'MILK\',\'SHEEP\':\'WOOL\'}\n\n@dataclass(frozen=True)\nclass OpponentSnapshot:\n step:int;crops:Mapping[str,int];mature:Mapping[str,int];pipeline:Mapping[str,float]\n structures:Mapping[str,int];animals:Mapping[str,int];workers:int;active_tiles:int;land:int\n\ndef parse_snapshot(state:GameState,mode:Mode=\'FULL_OPPONENT\')->OpponentSnapshot:\n crops=Counter();mature=Counter();pipeline=Counter();structures=Counter();animals=Counter();active=0\n for row in state.opponent.tiles:\n  for raw in row:\n   if not isinstance(raw,Mapping):continue\n   kind=raw.get(\'kind\');active+=kind not in (None,\'WEED\')\n   if kind==\'PLANT\':\n    crop=str(raw.get(\'crop\'));crops[crop]+=1;age=max(0,state.day-int(raw.get(\'planted_day\',state.day)));first,maxyield=CROP_DATA.get(crop,(30,1))\n    near=max(0.0,min(1.0,(age+2)/max(1,first)));pipeline[crop]+=near*max(1,int(raw.get(\'yield_units\',1)))*.6\n    mature[crop]+=int(age>=first and int(raw.get(\'yield_units\',0))>0)\n   elif kind in (\'COOP\',\'PASTURE\'):\n    structures[str(kind)]+=1\n    if raw.get(\'animal\'):animals[str(raw[\'animal\'])]+=1\n if mode==\'STATIC_SNAPSHOT\':pipeline=Counter({c:float(n) for c,n in crops.items()})\n return OpponentSnapshot(state.step,dict(crops),dict(mature),dict(pipeline),dict(structures),dict(animals),\n                         1+len(state.opponent.hands),int(active),len(state.opponent.unlocked_quadrants))\n\n@dataclass\nclass OpponentHistory:\n window:int=12;points:deque=field(default_factory=deque);resets:int=0\n def update(self,snapshot:OpponentSnapshot):\n  if self.points and snapshot.step<=self.points[-1].step:self.points.clear();self.resets+=1\n  self.points.append(snapshot)\n  while len(self.points)>self.window:self.points.popleft()\n def confidence(self)->float:\n  if not self.points:return 0.0\n  persistence=min(1.0,len(self.points)/6);scale=min(1.0,self.points[-1].active_tiles/12)\n  return persistence*scale\n\ndef animal_pipeline(snapshot:OpponentSnapshot)->dict[str,float]:\n out=Counter()\n for animal,n in snapshot.animals.items():out[ANIMAL_PRODUCT.get(animal,animal)]+=float(n)*.5\n return dict(out)\n\ndef predicted_production(snapshot:OpponentSnapshot,mode:Mode)->dict[str,float]:\n out=Counter(snapshot.pipeline)\n if mode==\'FULL_OPPONENT\':out.update(animal_pipeline(snapshot))\n return dict(out)\n\ndef supply_pressure(snapshot:OpponentSnapshot,history:OpponentHistory,mode:Mode)->dict[str,float]:\n confidence=1.0 if mode==\'STATIC_SNAPSHOT\' else history.confidence();production=predicted_production(snapshot,mode)\n return {p:min(1.0,float(v)/12.0)*confidence for p,v in production.items()}\n\ndef adjusted_prices(state:GameState,history:OpponentHistory,mode:Mode,strength:float=.10,horizon_days:int=4)->dict[str,int]:\n if mode==\'CONTROL\' or state.remaining_turns<=max(48,horizon_days*24):return dict(state.market_prices)\n snapshot=parse_snapshot(state,mode);pressure=supply_pressure(snapshot,history,mode);result=dict(state.market_prices)\n for crop in CROP_DATA:\n  base=int(state.market_prices.get(crop,1));result[crop]=max(1,int(round(base*(1-strength*pressure.get(crop,0.0)))))\n return result\n')
_load('agent_v9.config', '"""Frozen, explainable V9 candidate configuration."""\nfrom dataclasses import dataclass\nfrom agent_v8.opponent import Mode\n@dataclass(frozen=True)\nclass V9Config:\n mode:Mode=\'FULL_OPPONENT\';strength:float=.075;horizon_days:int=3;max_hands:int=6\n managed_plots:int=24;max_cows:int=1;fertilizer:bool=True;buy_land:bool=False\nDEFAULT_CONFIG=V9Config()\n')
_load('agent_v9.state', '"""V8 parses only the official shared farm payload for opponent state."""\nfrom __future__ import annotations\nfrom dataclasses import dataclass\nfrom typing import Any,Mapping\nfrom agent_v6.state import GameState as V6GameState,Position,StructureState\n\ndef _get(v:Any,k:str,d=None):return v.get(k,d) if isinstance(v,Mapping) else getattr(v,k,d)\n\n@dataclass(frozen=True)\nclass OpponentFarm:\n    player:int;money:float;farmer:Position;hands:tuple[Position,...]\n    unlocked_quadrants:tuple[str,...];hires_today:int;tiles:tuple[tuple[Any,...],...]\n\n@dataclass(frozen=True)\nclass GameState(V6GameState):\n    opponent:OpponentFarm\n    @classmethod\n    def from_observation(cls,obs:Any)->"GameState":\n        base=V6GameState.from_observation(obs);farms=_get(obs,\'farms\',()) or ();oid=1-base.player\n        if oid<0 or oid>=len(farms):raise ValueError(\'opponent public farm unavailable\')\n        f=farms[oid];farmer=_get(f,\'farmer\',(0,0));hands=_get(f,\'hands\',()) or ()\n        opponent=OpponentFarm(oid,float(_get(f,\'money\',0)),(int(farmer[0]),int(farmer[1])),\n            tuple((int(p[0]),int(p[1])) for p in hands),tuple(_get(f,\'unlocked_quadrants\',()) or ()),\n            int(_get(f,\'hires_today\',0)),tuple(tuple(row) for row in (_get(f,\'tiles\',()) or ())))\n        return cls(**base.__dict__,opponent=opponent)\n')
_load('agent_v9.workers', '"""V8 worker primitives with a V9-only configurable economic hand cap."""\nfrom agent_v4.workers import *  # noqa: F401,F403\nfrom agent_v4.workers import hire_cost\n\ndef hiring_orders_v9(state,max_hands,estimated_work,cash_reserve=200.0):\n if not 0<=max_hands<=6:raise ValueError(\'max_hands must be between 0 and 6\')\n current=len(state.hands);slots=max(0,max_hands-current)\n if slots==0 or state.remaining_turns<=2 or state.hour>=22:return []\n orders=[];money=state.money;useful=min(23-state.hour,state.remaining_turns-1)\n for offset in range(slots):\n  cost=hire_cost(state.hires_today+offset);marginal=max(0,estimated_work-(current+len(orders)+1));value=min(useful,marginal)*2.0\n  if useful<=0 or marginal<=0 or value<=cost or money-cost<cash_reserve:break\n  orders.append([\'HIRE\']);money-=cost\n return orders\n')
_load('agent_v9.strategy', '"""V9 integration: V8 opponent model with configurable final labor cap."""\nfrom dataclasses import replace\nfrom agent_v4.endgame import is_final_day\nfrom agent_v4.market import build_market_orders\nfrom agent_v4.workers import assign_tasks,task_action,units\nfrom agent_v6.animals import animal_tasks,format_animal_action,required_market_orders,structure_positions\nfrom agent_v6.strategy import SAFE_ACTION,_crop_tasks\nfrom agent_v8.opponent import OpponentHistory,adjusted_prices,parse_snapshot\nfrom agent_v9.config import V9Config\nfrom agent_v9.state import GameState\nfrom agent_v9.workers import hiring_orders_v9\n\ndef _expanded_crop_tasks(state,capacity):\n from agent_v5.strategy import build_crop_plan,generate_tasks\n from agent_v4.workers import WorkTask\n from agent_v5 import crops\n plan=build_crop_plan(state,capacity);result=[]\n for task in generate_tasks(state,capacity,plan):\n  tile=state.tile_at(task.target);crop=crops.crop_type(tile) or task.crop\n  result.append(WorkTask(task.kind,task.target,task.priority,3 if task.kind==\'HARVEST\' else 0,float(state.market_prices.get(crop,0)) if crop else 0.0,task.crop))\n return plan,result\n\ndef decide(state:GameState,history:OpponentHistory,config:V9Config):\n snapshot=parse_snapshot(state,config.mode);history.update(snapshot)\n chosen=state if config.mode==\'CONTROL\' else replace(state,market_prices=adjusted_prices(state,history,config.mode,config.strength,config.horizon_days))\n proposed=tuple(\'COW\' for _ in range(config.max_cows));positions=structure_positions(chosen,len(proposed));crop_capacity=max(12,min(config.managed_plots,len(chosen.unlocked_quadrants)*25-len(positions)))\n plan,crop_tasks=(_expanded_crop_tasks(chosen,crop_capacity) if config.buy_land else _crop_tasks(chosen,crop_capacity));empty={p:c for p,c in plan.targets.items() if chosen.tile_at(p).is_empty}\n market=build_market_orders(chosen,empty)\n if any(s.animal for s in chosen.structures):\n  reserve=sum(1 for s in chosen.structures if s.animal);adjusted=[]\n  for order in market:\n   if order[:2]==[\'SELL\',\'WHEAT\']:\n    n=max(0,int(order[2])-reserve)\n    if n:adjusted.append([\'SELL\',\'WHEAT\',n])\n   else:adjusted.append(order)\n  market=adjusted\n market+=required_market_orders(chosen,proposed,positions,chosen.day<29)\n tasks=crop_tasks+animal_tasks(chosen,proposed,positions,config.fertilizer);hires=hiring_orders_v9(chosen,config.max_hands,len(tasks)+len(empty))\n assignments=assign_tasks(chosen,tasks);active=units(chosen);actions=[]\n for unit in active:\n  task=assignments.get(unit.index);actions.append(format_animal_action(chosen,unit,task) or task_action(chosen,unit,task))\n if is_final_day(chosen.day) and chosen.remaining_turns<4:hires=[]\n market=market+hires\n if config.buy_land and len(chosen.unlocked_quadrants)==1:\n  from agent_v5.land import should_buy_next_land\n  best=max((x.score for x in plan.scores.values()),default=0.0)\n  if should_buy_next_land(chosen,1,config.managed_plots,best,0):market.append([\'BUY_LAND\'])\n market=[o for o in market if o and (config.buy_land or o[0]!=\'BUY_LAND\')]\n return {\'farmer\':actions[0],\'hands\':actions[1:],\'market\':market}\n')
